declare(strict_types=1);require_once __DIR__.'/../lib/CronGuard.php';rx_cron_authorize();require_once __DIR__.'/../config.php';require_once __DIR__.'/../lib/UpdateSources.php';rx_cron_telemetry_start($pdo,'update_check');$s=RedFoxUpdateSources::settings($pdo);if(empty($s['auto_check']))exit;$current=trim((string)file_get_contents(dirname(__DIR__).'/version'));$allow=!empty($s['allow_unsigned_local']);$candidates=[];try{$local=RedFoxUpdateSources::checkLocalFolders($pdo,dirname(__DIR__),$current,$allow);if($local)$candidates[]=$local;}catch(Throwable$e){}if(!empty($s['github_repo'])){try{$gh=RedFoxUpdateSources::checkGitHub($pdo);$gh['source']='github';$gh['file']=null;$candidates[]=$gh;}catch(Throwable$e){$pdo->prepare('UPDATE update_sources SET last_check_at=?,last_error=? WHERE id=1')->execute([time(),mb_substr(redfox_exception_fingerprint($e),0,900)]);}}if(!$candidates){echo json_encode(['ok'=>true,'update'=>false]);exit;}usort($candidates,fn($a,$b)=>version_compare($b['version'],$a['version']));$best=$candidates[0];$pdo->prepare('UPDATE update_sources SET last_check_at=?,last_version=?,last_source=?,last_file=?,last_url=?,last_error=NULL WHERE id=1')->execute([time(),$best['version'],$best['source'],$best['file']??null,$best['url']??null]);echo json_encode(['ok'=>true,'update'=>version_compare($best['version'],$current,'>'),'version'=>$best['version'],'source'=>$best['source']]);
